// Tres cotizaciones con la misma fórmula copiada en cada lugar (reglas inventadas)
// Regla: USD 20 de salida + USD 0,90 por km; más de 1000 kg lleva 15 % de recargo; mínimo USD 35

// Cotización 1: Rosario, 300 km, 500 kg
let costo1 = 20 + 300 * 0.9;
if (500 > 1000) costo1 = costo1 * 1.15;
if (costo1 < 35) costo1 = 35;

// Cotización 2: Mar del Plata, 400 km, 1500 kg
let costo2 = 20 + 400 * 0.9;
if (1500 > 1000) costo2 = costo2 * 1.15;
if (costo2 < 35) costo2 = 35;

// Cotización 3: Luján, 70 km, 200 kg (la tarifa por km quedó en 0.8 por un error de copia)
let costo3 = 20 + 70 * 0.8;
if (200 > 1000) costo3 = costo3 * 1.15;
if (costo3 < 35) costo3 = 35;

console.log(costo1, costo2, costo3);

// Declaración: los nombres entre paréntesis son los PARÁMETROS (reglas inventadas)
function calcularFlete(peso, km) {
  let costo = 20 + km * 0.9;            // USD 20 de salida + USD 0,90 por km
  if (peso > 1000) {
    costo = costo * 1.15;               // 15 % de recargo por carga pesada
  }
  if (costo < 35) {
    costo = 35;                         // mínimo por viaje
  }
  return Math.round(costo * 100) / 100; // se devuelve redondeado a centavos
}

// Llamadas: los valores entre paréntesis son los ARGUMENTOS
console.log(calcularFlete(500, 300));   // Rosario
console.log(calcularFlete(1500, 400));  // Mar del Plata
console.log(calcularFlete(200, 70));    // Luján
console.log(calcularFlete(200, 10));    // viaje corto: aplica el mínimo

// Un argumento puede ser cualquier expresión: se calcula ANTES de entrar a la función
const kmBase = 100;
console.log(calcularFlete(2 * 600, kmBase + 50));

// Tres cosas que hace return
function calcularFlete(peso, km) {
  let costo = 20 + km * 0.9;
  if (peso > 1000) costo = costo * 1.15;
  return Math.round(costo * 100) / 100;
  console.log("esta línea nunca se ejecuta");   // después de return, la función ya terminó
}

// Versión equivocada: muestra el resultado pero no lo devuelve
function mostrarFlete(peso, km) {
  const costo = 20 + km * 0.9;
  console.log("costo calculado:", costo);       // se ve en pantalla...
}                                               // ...pero no hay return

const a = calcularFlete(500, 100);
const b = mostrarFlete(500, 100);
console.log("a vale", a);
console.log("b vale", b);                       // una función sin return devuelve undefined
console.log("a + 1 =", a + 1, "| b + 1 =", b + 1);

// Valor por defecto: si no pasás ese argumento, se usa el que está después del =
function calcularFlete(peso, km, tarifaKm = 0.9) {
  let costo = 20 + km * tarifaKm;
  if (peso > 1000) costo = costo * 1.15;
  return Math.round(costo * 100) / 100;
}

console.log(calcularFlete(500, 100));          // sin tercer argumento: usa 0.9
console.log(calcularFlete(500, 100, 1.2));     // con tercer argumento: usa 1.2
console.log(calcularFlete(500, 100, undefined)); // undefined también activa el defecto
console.log(calcularFlete(500, 100, null));    // null NO lo activa: se usa como valor (0)

// Sin defecto y sin el argumento, el parámetro vale undefined y la cuenta se contagia
function sinDefecto(peso, km, tarifaKm) {
  return 20 + km * tarifaKm;
}
console.log(sinDefecto(500, 100));

// Tres formas de escribir lo mismo
function iva1(precio) { return precio * 1.21; }          // declaración
const iva2 = function (precio) { return precio * 1.21; }; // expresión: una función guardada en una constante
const iva3 = (precio) => precio * 1.21;                  // flecha con retorno implícito

console.log(iva1(100), iva2(100), iva3(100));

// Con llaves hay que escribir return (si no, devuelve undefined)
const mayor = (a, b) => {
  if (a > b) return a;
  return b;
};
console.log(mayor(3, 9));
const olvido = (a, b) => { a > b ? a : b };               // sin return dentro de las llaves
console.log(olvido(3, 9));

// Una función es un valor: se guarda en una variable y se pasa como argumento
const sinDescuento = (precio) => precio;
const mayorista = (precio) => precio * 0.9;
const liquidacion = (precio) => precio * 0.6;

function precioFinal(precio, regla) {
  return regla(precio);        // llama a la función que le pasaron
}

console.log(precioFinal(1000, sinDescuento));
console.log(precioFinal(1000, mayorista));
console.log(precioFinal(1000, liquidacion));
console.log(typeof mayorista);   // "function"

// También se puede devolver una función
const conRecargo = (porcentaje) => (precio) => precio * (1 + porcentaje / 100);
const iva21 = conRecargo(21);
console.log(iva21(100));

// Dos tipos de función
function calcularFlete(peso, km) {                 // pura: mismos argumentos, mismo resultado; no toca nada de afuera
  let costo = 20 + km * 0.9;
  if (peso > 1000) costo = costo * 1.15;
  return Math.round(costo * 100) / 100;
}

let totalFacturado = 0;                            // una variable que vive afuera de las funciones
let cotizaciones = 0;

function cotizar(peso, km) {                       // con efectos secundarios: modifica variables de afuera
  const costo = calcularFlete(peso, km);
  totalFacturado = totalFacturado + costo;
  cotizaciones = cotizaciones + 1;
  console.log("cotización n.º", cotizaciones, "->", costo);
  return costo;
}

console.log(calcularFlete(500, 100), calcularFlete(500, 100));   // siempre lo mismo
cotizar(500, 100);
cotizar(500, 100);                                 // mismos argumentos, pero el mundo ya cambió
console.log("total acumulado:", totalFacturado);

// ANTES: una función que hace tres cosas a la vez (calcula, imprime y acumula)
let totalDelDia = 0;
function procesarEnvio(peso, km, cliente) {
  let costo = 20 + km * 0.9;
  if (peso > 1000) costo = costo * 1.15;
  if (costo < 35) costo = 35;
  console.log("Cliente: " + cliente + " | Flete: USD " + costo.toFixed(2));
  totalDelDia = totalDelDia + costo;
  return costo;
}
procesarEnvio(500, 300, "Ferretería Sur");
procesarEnvio(1500, 400, "Distribuidora Norte");
console.log("Total del día (antes):", totalDelDia.toFixed(2));

// DESPUÉS: cada función hace una sola cosa, con un nombre que dice cuál
function calcularFlete(peso, km) {
  let costo = 20 + km * 0.9;
  if (peso > 1000) costo = costo * 1.15;
  if (costo < 35) costo = 35;
  return Math.round(costo * 100) / 100;
}
function formatearLinea(cliente, costo) {
  return "Cliente: " + cliente + " | Flete: USD " + costo.toFixed(2);
}
function sumar(a, b) {
  return a + b;
}

const flete1 = calcularFlete(500, 300);
console.log(formatearLinea("Ferretería Sur", flete1));
const flete2 = calcularFlete(1500, 400);
console.log(formatearLinea("Distribuidora Norte", flete2));
console.log("Total del día (después):", sumar(flete1, flete2).toFixed(2));

// ¿Cuántas llamadas anidadas aguanta el motor? Una función que se llama a sí misma sin parar
let profundidad = 0;
function bajar() {
  profundidad = profundidad + 1;
  bajar();                           // nunca vuelve: cada llamada espera a la siguiente
}
try {
  bajar();
} catch (error) {
  console.log(error.name + ": " + error.message);
  console.log("llamadas anidadas antes de cortar:", profundidad);
}

function suma(a, b) { return a + b; }
function conFuncion(n) { let s = 0; for (let i = 0; i < n; i++) s = suma(s, i); return s; }
function sinFuncion(n) { let s = 0; for (let i = 0; i < n; i++) s = s + i; return s; }
const N = 20000000;
for (let r = 0; r < 2; r++) {
  let t = Date.now(); const x = conFuncion(N); const t1 = Date.now() - t;
  t = Date.now(); const y = sinFuncion(N); const t2 = Date.now() - t;
  console.log("con función:", t1, "ms | sin función:", t2, "ms |", x === y);
}
